1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.security.NoSuchAlgorithmException;
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner == null ? null : owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(owner == null ? null : "
29	            + "Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
30	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
31	    @Mapping(target = "locality", expression = "java(deriveLocality(owner))")
32	    @Mapping(target = "timezone", expression = "java(deriveTimezone(owner))")
33	    @Mapping(target = "contactPreference",
34	        expression = "java(owner == null ? null : "
35	            + "(owner.getEmail() != null && !owner.getEmail().isEmpty() ? \"EMAIL\" : \"PHONE\"))")
36	    @Mapping(target = "identityKey", expression = "java(deriveIdentityKey(owner))")
37	    @Mapping(target = "checkDigit", expression = "java(deriveCheckDigit(owner))")
38	    @Mapping(target = "ageBand", expression = "java(deriveAgeBand(owner))")
39	    @Mapping(target = "telephoneDisplay", expression = "java(deriveTelephoneDisplay(owner))")
40	    @Mapping(target = "salutation", expression = "java(deriveSalutation(owner))")
41	    @Mapping(target = "fiscalYear", expression = "java(deriveFiscalYear(owner))")
42	    @Mapping(target = "selfLink",
43	        expression = "java(owner == null || owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    Owner toOwner(OwnerDto ownerDto);
47	
48	    @Mapping(target = "id", ignore = true)
49	    @Mapping(target = "pets", ignore = true)
50	    Owner toOwner(OwnerFieldsDto ownerDto);
51	
52	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
53	
54	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
55	
56	    /**
57	     * Derive the owner's locality (region) from its region-and-hash {@code customerCode}: the
58	     * {@code REGION} portion is the segment before the first {@code '-'} (e.g. {@code "NSW-1A2B3C4D"}
59	     * yields {@code "NSW"}). This shares the identity's region derivation, where the postcode range
60	     * takes precedence (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and the city-to-region table is
61	     * the fallback. For an owner without a {@code customerCode} the same region is recomputed directly
62	     * from the postcode then city, otherwise "UNKNOWN".
63	     */
64	    default String deriveLocality(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        String customerCode = owner.getCustomerCode();
69	        if (customerCode != null) {
70	            int dash = customerCode.indexOf('-');
71	            if (dash > 0) {
72	                return customerCode.substring(0, dash);
73	            }
74	        }
75	        String postcode = owner.getPostcode();
76	        if (postcode != null) {
77	            try {
78	                int pc = Integer.parseInt(postcode.trim());
79	                if (pc >= 2000 && pc <= 2099) {
80	                    return "NSW";
81	                }
82	                if (pc >= 3000 && pc <= 3099) {
83	                    return "VIC";
84	                }
85	                if (pc >= 4000 && pc <= 4099) {
86	                    return "QLD";
87	                }
88	            }
89	            catch (NumberFormatException ignored) {
90	                // not a numeric postcode; fall back to the city-to-region table
91	            }
92	        }
93	        String city = owner.getCity();
94	        if ("Sydney".equals(city)) {
95	            return "NSW";
96	        }
97	        if ("Melbourne".equals(city)) {
98	            return "VIC";
99	        }
100	        if ("Brisbane".equals(city)) {
101	            return "QLD";
102	        }
103	        return "UNKNOWN";
104	    }
105	
106	    /**
107	     * Derive the owner's IANA timezone from its locality/region using the fixed region-to-timezone
108	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). The region is
109	     * the same value reported as {@code locality}. Returns null when the owner is absent or the region
110	     * has no known timezone.
111	     */
112	    default String deriveTimezone(Owner owner) {
113	        if (owner == null) {
114	            return null;
115	        }
116	        String region = deriveLocality(owner);
117	        if ("NSW".equals(region)) {
118	            return "Australia/Sydney";
119	        }
120	        if ("VIC".equals(region)) {
121	            return "Australia/Melbourne";
122	        }
123	        if ("QLD".equals(region)) {
124	            return "Australia/Brisbane";
125	        }
126	        return null;
127	    }
128	
129	    /**
130	     * Derive the owner's check digit: a single Luhn check digit (0-9) computed over the
131	     * digits contained in the owner's customerCode. Non-digit characters are ignored.
132	     * Returns null when the owner or its customerCode is absent.
133	     */
134	    default Integer deriveCheckDigit(Owner owner) {
135	        if (owner == null || owner.getCustomerCode() == null) {
136	            return null;
137	        }
138	        String code = owner.getCustomerCode();
139	        int sum = 0;
140	        boolean dbl = true;
141	        for (int i = code.length() - 1; i >= 0; i--) {
142	            char c = code.charAt(i);
143	            if (c < '0' || c > '9') {
144	                continue;
145	            }
146	            int d = c - '0';
147	            if (dbl) {
148	                d *= 2;
149	                if (d > 9) {
150	                    d -= 9;
151	                }
152	            }
153	            sum += d;
154	            dbl = !dbl;
155	        }
156	        return (10 - (sum % 10)) % 10;
157	    }
158	
159	    /**
160	     * Derive the owner's age band from its birthDate against the registrationDate: 'MINOR' when
161	     * under 18, 'ADULT' from 18 to 64, and 'SENIOR' at 65 or older. The age is the number of whole
162	     * years between birthDate and registrationDate (falling back to the current date when the owner
163	     * has no registrationDate). Returns null when the owner or its birthDate is absent, so no
164	     * ageBand is reported.
165	     */
166	    default String deriveAgeBand(Owner owner) {
167	        if (owner == null || owner.getBirthDate() == null) {
168	            return null;
169	        }
170	        java.time.LocalDate reference = owner.getRegistrationDate() != null
171	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
172	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
173	        if (age < 18) {
174	            return "MINOR";
175	        }
176	        if (age < 65) {
177	            return "ADULT";
178	        }
179	        return "SENIOR";
180	    }
181	
182	    /**
183	     * Known E.164 country calling codes, longest first, used to split a stored telephone into its
184	     * country code and national digits. A number whose code is not listed falls back to a two-digit
185	     * country code, the most common E.164 length.
186	     */
187	    String[] KNOWN_CALLING_CODES = { "61", "1" };
188	
189	    /**
190	     * Format the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
191	     * the national digits grouped in threes (e.g. {@code "+61412345678"} becomes
192	     * {@code "+61 412 345 678"}). Returns null when the owner or its telephone is absent, and returns
193	     * the value unchanged when it is not in E.164 form.
194	     */
195	    default String deriveTelephoneDisplay(Owner owner) {
196	        if (owner == null || owner.getTelephone() == null) {
197	            return null;
198	        }
199	        String telephone = owner.getTelephone();
200	        if (!telephone.startsWith("+")) {
201	            return telephone;
202	        }
203	        String digits = telephone.substring(1);
204	        int codeLength = 2;
205	        for (String code : KNOWN_CALLING_CODES) {
206	            if (digits.startsWith(code) && digits.length() > code.length()) {
207	                codeLength = code.length();
208	                break;
209	            }
210	        }
211	        if (digits.length() <= codeLength) {
212	            return telephone;
213	        }
214	        String national = digits.substring(codeLength);
215	        StringBuilder display = new StringBuilder("+").append(digits, 0, codeLength);
216	        for (int i = 0; i < national.length(); i += 3) {
217	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
218	        }
219	        return display.toString();
220	    }
221	
222	    /**
223	     * Derive the owner's salutation: the honorific {@code title} followed by a single space and the
224	     * {@code lastName} (e.g. {@code "DR Who"}). When the owner has no title (null or blank) the
225	     * salutation is just the {@code lastName}. Returns null when the owner is absent.
226	     */
227	    default String deriveSalutation(Owner owner) {
228	        if (owner == null) {
229	            return null;
230	        }
231	        String title = owner.getTitle();
232	        String lastName = owner.getLastName();
233	        if (title == null || title.isBlank()) {
234	            return lastName;
235	        }
236	        return title + " " + lastName;
237	    }
238	
239	    /**
240	     * Derive the owner's fiscal year from its business-day-adjusted {@code registrationDate},
241	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year. The fiscal
242	     * year starts on 1 July and is labelled by the calendar year in which it ends, so a
243	     * registrationDate on or after 1 July belongs to the fiscal year ending the following calendar
244	     * year. Returns null when the owner or its registrationDate is absent.
245	     */
246	    default String deriveFiscalYear(Owner owner) {
247	        if (owner == null || owner.getRegistrationDate() == null) {
248	            return null;
249	        }
250	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
251	        int fiscalYear = registrationDate.getMonthValue() >= java.time.Month.JULY.getValue()
252	            ? registrationDate.getYear() + 1 : registrationDate.getYear();
253	        return String.format("FY%02d", fiscalYear % 100);
254	    }
255	
256	    /**
257	     * Derive the owner's {@code identityKey}: the 64-character lower-case SHA-256 hex digest over
258	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone and
259	     * email are the owner's already-normalized stored values (E.164 telephone, lower-cased email); a
260	     * null email contributes an empty middle segment. Returns null when the owner is absent. This is
261	     * the same key duplicate detection compares on create.
262	     */
263	    default String deriveIdentityKey(Owner owner) {
264	        if (owner == null) {
265	            return null;
266	        }
267	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
268	        String email = owner.getEmail() == null ? "" : owner.getEmail();
269	        return sha256Hex(telephone + "|" + email + "|" + soundex(owner.getLastName()));
270	    }
271	
272	    /**
273	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
274	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
275	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent. The
276	     * result is padded with zeros to exactly four characters. A null or letterless name yields "".
277	     */
278	    private static String soundex(String name) {
279	        if (name == null) {
280	            return "";
281	        }
282	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
